}

// Clean up the content (remove markdown formatting, extra whitespace)
content = content.trim().replace(/^```json\s*/, '').replace(/\s*```$/, '');

try {
  const parsedContent = JSON.parse(content);
  return {
    json: parsedContent
  };
} catch (error) {
  throw new Error('Failed to parse JSON from Plot Architect: ' + error.message + '\nContent: ' + content.substring(0, 200) + '...');
}

// Split the story into scenes for image generation
const response = $input.first().json;

// Handle different response structures from Gemini agents
let storyText;
if (response.output) {
  // LangChain agent response structure
  storyText = response.output;
} else if (response.text) {
  // Direct text response
  storyText = response.text;
} else if (response.content && response.content[0] && response.content[0].text) {
  // Anthropic-style response structure
  storyText = response.content[0].text;
} else if (typeof response === 'string') {
  // String response
  storyText = response;
} else {
  // Try to find text in the response
  storyText = response.message || response.response || JSON.stringify(response);
}

const plotData = $('Parse Plot JSON').first().json;

// Split story into paragraphs
const paragraphs = storyText.split('\n\n').filter(p => p.trim().length > 0);

// Create scenes based on plot points
const scenes = [];
const plotPoints = plotData.plot_points || [];

for (let i = 0; i < Math.min(paragraphs.length, plotPoints.length); i++) {
  scenes.push({
    scene_number: i + 1,
    scene_title: plotPoints[i]?.title || `Scene ${i + 1}`,
    scene_text: paragraphs[i].trim(),
    story_title: plotData.title,
    characters: plotData.characters
  });
}

return scenes.map(scene => ({ json: scene }));

// Generate a compelling cover art prompt based on the story
const plotData = $('Parse Plot JSON').first().json;
const narrativeResponse = $('Narrative Weaver').first().json;

// Handle different response structures from Gemini agents
let storyText;
if (narrativeResponse.output) {
  storyText = narrativeResponse.output;
} else if (narrativeResponse.text) {
  storyText = narrativeResponse.text;
} else if (narrativeResponse.content && narrativeResponse.content[0] && narrativeResponse.content[0].text) {
  storyText = narrativeResponse.content[0].text;
} else if (typeof narrativeResponse === 'string') {
  storyText = narrativeResponse;
} else {
  storyText = narrativeResponse.message || narrativeResponse.response || JSON.stringify(narrativeResponse);
}

// Extract key elements from the story for cover art
const title = plotData.title || 'Story Title';
const genre = plotData.genre || 'Adventure';
const moral = plotData.moral_lesson_summary || 'A story about friendship';
const setting = plotData.setting || 'An exciting adventure';

// Create a compelling cover art prompt
const coverPrompt = `Professional children's book cover art, Pixar animation style, ultra-high quality digital illustration, vibrant colors, dramatic lighting. Angel is a confident 12-year-old boy with curly black hair wearing a red hoodie. Jayson is a curious 10-year-old boy with cornrow braids wearing a blue t-shirt. The cover should capture the essence of: ${title}. Genre: ${genre}. Setting: ${setting}. COVER SPECIFICATIONS: Standard children's book cover dimensions (8.5" x 11" or 3:4 aspect ratio), Title "${title}" prominently displayed at the top in an elegant, readable font with subtle glow effect, Author name "StorySphere AI" at the bottom, Professional book cover layout with proper margins and spacing, High contrast, detailed, award-winning illustration quality, 4K resolution, cinematic composition, Perfect for printing and digital display, Visually stunning and immediately captures attention, Consistent with professional children's book publishing standards`;

return {
  json: {
    coverPrompt: coverPrompt,
    storyTitle: title,
    storyText: storyText,
    plotData: plotData,
    genre: genre,
    setting: setting,
    moral: moral
  }
};

// Check if image generation is complete and extract image URL
const response = $input.first().json;

console.log('Full response:', JSON.stringify(response, null, 2));
console.log('Response status:', response.status);
console.log('Has images array:', !!response.images);
console.log('Images length:', response.images?.length);

// Check if we already have images (completed response)
if (response.images && Array.isArray(response.images) && response.images.length > 0) {
  console.log('Image found, extracting URL:', response.images[0].url);
  return {
    json: {
      imageUrl: response.images[0].url,
      requestId: response.request_id || 'unknown',
      status: 'COMPLETED',
      originalResponse: response
    }
  };
}

// If still in queue, throw error to trigger retry
if (response.status === 'IN_QUEUE') {
  const queuePos = response.metrics?.queue_position || 'unknown';
  throw new Error(`Image still generating. Queue position: ${queuePos}. Retrying...`);
}

// If completed status but no images (fallback)
if (response.status === 'COMPLETED') {
  throw new Error('No images found in completed response');
}

// Handle failed status
if (response.status === 'FAILED') {
  throw new Error(`Image generation failed: ${response.error || 'Unknown error'}`);
}

// If no status but we have images, treat as completed
if (response.images && Array.isArray(response.images) && response.images.length > 0) {
  return {
    json: {
      imageUrl: response.images[0].url,
      requestId: response.request_id || 'unknown',
      status: 'COMPLETED',
      originalResponse: response
    }
  };
}

// Handle other cases
throw new Error(`Unexpected response format. Status: ${response.status || 'undefined'}, Has images: ${!!response.images}`);

// Aggregate all image URLs after the loop
const allScenes = $input.all();
const imageUrls = allScenes.map(scene => {
  const storageData = scene.json;
  return `https://firebasestorage.googleapis.com/v0/b/${storageData.bucket}/o/${encodeURIComponent(storageData.name)}?alt=media`;
});

const storyData = $('Parse Plot JSON').first().json;
const narrativeResponse = $('Narrative Weaver').first().json;
const coverArtData = $('Generate Cover Art').first().json;

// Handle different response structures from Gemini agents
let storyText;
if (narrativeResponse.output) {
  // LangChain agent response structure
  storyText = narrativeResponse.output;
} else if (narrativeResponse.text) {
  // Direct text response
  storyText = narrativeResponse.text;
} else if (narrativeResponse.content && narrativeResponse.content[0] && narrativeResponse.content[0].text) {
  // Anthropic-style response structure
  storyText = narrativeResponse.content[0].text;
} else if (typeof narrativeResponse === 'string') {
  // String response
  storyText = narrativeResponse;
} else {
  // Try to find text in the response
  storyText = narrativeResponse.message || narrativeResponse.response || JSON.stringify(narrativeResponse);
}

// Get cover art URL
let coverArtUrl = null;
if (coverArtData.images && coverArtData.images.length > 0) {
  coverArtUrl = coverArtData.images[0].url;
}

return {
  json: {
    imageUrls: imageUrls,
    coverArtUrl: coverArtUrl,
    storyTitle: storyData.title,
    storyText: storyText,
    plotData: storyData,
    sceneCount: imageUrls.length
  }
};

